import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

async function getRazorpayCredentials(supabase: any) {
  const envKeyId = Deno.env.get("RAZORPAY_KEY_ID") || "";
  const envKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET") || "";
  if (envKeyId && envKeySecret) {
    return { keyId: envKeyId, keySecret: envKeySecret };
  }

  const { data: rows } = await supabase
    .from("admin_settings")
    .select("key, value, is_active")
    .in("key", ["razorpay_key_id", "razorpay_key_secret"])
    .eq("is_active", true);

  const map: Record<string, string> = {};
  for (const r of rows || []) {
    if (r?.key && r?.value) map[r.key] = String(r.value);
  }

  return {
    keyId: map.razorpay_key_id || envKeyId,
    keySecret: map.razorpay_key_secret || envKeySecret,
  };
}

/**
 * Create a Razorpay Route transfer to a linked account.
 * Returns transfer id on success.
 */
async function createRouteTransfer(opts: {
  keyId: string;
  keySecret: string;
  accountId: string;
  amountPaise: number;
  settlementId: string;
  orderId: string;
}): Promise<{ ok: true; transferId: string } | { ok: false; error: string }> {
  const authBasic = "Basic " + btoa(`${opts.keyId}:${opts.keySecret}`);
  const res = await fetch("https://api.razorpay.com/v1/transfers", {
    method: "POST",
    headers: {
      Authorization: authBasic,
      "Content-Type": "application/json",
    },
    body: JSON.stringify({
      account: opts.accountId,
      amount: opts.amountPaise,
      currency: "INR",
      notes: {
        settlement_id: opts.settlementId,
        order_id: opts.orderId,
        source: "sociva_process_settlements",
      },
    }),
  });

  const body = await res.json().catch(() => ({}));
  if (!res.ok) {
    const msg =
      body?.error?.description ||
      body?.error?.reason ||
      `razorpay_transfer_http_${res.status}`;
    return { ok: false, error: String(msg) };
  }

  const transferId = body?.id;
  if (!transferId) {
    return { ok: false, error: "razorpay_transfer_missing_id" };
  }
  return { ok: true, transferId: String(transferId) };
}

/**
 * Settlement eligibility + optional Razorpay Route payout cron.
 *
 * HONESTY CONTRACT:
 * - pending → eligible after cooldown/delivery/payment checks (always).
 * - eligible → settled ONLY when route is enabled AND a real transfer id
 *   is returned from Razorpay (seller must have razorpay_account_id).
 * - Never marks settled without razorpay_transfer_id.
 */
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const authHeader = req.headers.get("Authorization");
    const serviceRoleKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    if (!authHeader || authHeader !== `Bearer ${serviceRoleKey}`) {
      return new Response(
        JSON.stringify({ error: "Unauthorized — service role required" }),
        { status: 401, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const supabase = createClient(
      Deno.env.get("SUPABASE_URL")!,
      serviceRoleKey,
    );

    const { data: autoSetting } = await supabase
      .from("system_settings")
      .select("value")
      .eq("key", "auto_settle_enabled")
      .single();

    const autoEnabled = autoSetting?.value === "true";

    let force = false;
    try {
      const body = await req.json();
      force = body?.force === true;
    } catch {
      // No body is fine
    }

    if (!autoEnabled && !force) {
      return new Response(
        JSON.stringify({
          processed: 0,
          message: "Auto-settle is disabled. Pass force=true to override.",
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const { data: routeSetting } = await supabase
      .from("admin_settings")
      .select("value, is_active")
      .eq("key", "razorpay_route_enabled")
      .maybeSingle();

    const routeEnabled =
      routeSetting?.is_active === true &&
      String(routeSetting?.value || "").toLowerCase() === "true";

    const creds = routeEnabled
      ? await getRazorpayCredentials(supabase)
      : { keyId: "", keySecret: "" };

    // 1) Promote pending → eligible
    const { data: pendingSettlements, error: fetchErr } = await supabase
      .from("seller_settlements")
      .select("id, order_id, seller_id, net_amount, settlement_status")
      .eq("settlement_status", "pending")
      .lte("eligible_at", new Date().toISOString());

    if (fetchErr) throw fetchErr;

    let processed = 0;
    const errors: { id: string; error: string }[] = [];
    let transferred = 0;

    const { data: allTerminalRows } = await supabase
      .from("category_status_flows")
      .select("status_key, transaction_type")
      .eq("is_terminal", true)
      .eq("is_success", true);

    const terminalByWorkflow = new Map<string, Set<string>>();
    const allTerminalStatuses = new Set<string>();
    for (const r of allTerminalRows || []) {
      allTerminalStatuses.add(r.status_key);
      if (!terminalByWorkflow.has(r.transaction_type)) {
        terminalByWorkflow.set(r.transaction_type, new Set());
      }
      terminalByWorkflow.get(r.transaction_type)!.add(r.status_key);
    }

    for (const settlement of pendingSettlements || []) {
      const { data: orderData } = await supabase
        .from("orders")
        .select(
          "status, fulfillment_type, delivery_handled_by, order_type, transaction_type, payment_status",
        )
        .eq("id", settlement.order_id)
        .single();

      const orderPay = String(orderData?.payment_status || "");
      if (["refunded", "refund_initiated", "refund_processing"].includes(orderPay)) {
        await supabase
          .from("seller_settlements")
          .update({
            settlement_status: "on_hold",
            hold_reason: `Blocked: order payment_status=${orderPay}`,
            eligible_at: null,
            updated_at: new Date().toISOString(),
          })
          .eq("id", settlement.id)
          .in("settlement_status", ["pending", "eligible", "processing"]);
        errors.push({ id: settlement.id, error: `Order ${orderPay} — settlement held` });
        continue;
      }

      const orderWorkflow =
        orderData?.transaction_type ||
        orderData?.order_type ||
        "self_fulfillment";
      const relevantTerminals =
        terminalByWorkflow.get(orderWorkflow) || allTerminalStatuses;

      const isNonPlatformDelivery =
        orderData?.fulfillment_type === "self_pickup" ||
        orderData?.delivery_handled_by !== "platform";

      if (isNonPlatformDelivery) {
        if (!orderData || !relevantTerminals.has(orderData.status)) {
          errors.push({ id: settlement.id, error: "Order not completed" });
          continue;
        }
      } else {
        const { data: delivery } = await supabase
          .from("delivery_assignments")
          .select("status")
          .eq("order_id", settlement.order_id)
          .single();

        if (delivery?.status !== "delivered") {
          errors.push({ id: settlement.id, error: "Delivery not confirmed" });
          continue;
        }
      }

      const { data: payment } = await supabase
        .from("payment_records")
        .select("payment_status")
        .eq("order_id", settlement.order_id)
        .limit(1)
        .single();

      if (payment?.payment_status !== "paid") {
        errors.push({ id: settlement.id, error: "Payment not confirmed" });
        continue;
      }

      const { error: eligibleErr } = await supabase
        .from("seller_settlements")
        .update({ settlement_status: "eligible" })
        .eq("id", settlement.id);

      if (eligibleErr) {
        errors.push({ id: settlement.id, error: eligibleErr.message });
        continue;
      }

      await supabase.from("audit_log").insert({
        actor_id: null,
        action: "settlement_marked_eligible",
        target_type: "seller_settlements",
        target_id: settlement.id,
        society_id: null,
        metadata: {
          order_id: settlement.order_id,
          seller_id: settlement.seller_id,
          net_amount: settlement.net_amount,
          route_enabled: routeEnabled,
          transfer_attempted: false,
        },
      });

      processed++;
    }

    // 2) When Route enabled: transfer eligible settlements with linked accounts
    if (routeEnabled) {
      if (!creds.keyId || !creds.keySecret) {
        return new Response(
          JSON.stringify({
            processed,
            transferred: 0,
            errors: [
              ...errors,
              {
                id: "route",
                error: "razorpay_route_enabled but credentials missing",
              },
            ],
            route_enabled: true,
            message:
              "Eligible marked where possible; Route transfers skipped — Razorpay credentials missing.",
          }),
          {
            status: 200,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          },
        );
      }

      const { data: eligibleRows, error: eligErr } = await supabase
        .from("seller_settlements")
        .select("id, order_id, seller_id, net_amount, settlement_status, razorpay_transfer_id")
        .eq("settlement_status", "eligible")
        .is("razorpay_transfer_id", null)
        .limit(50);

      if (eligErr) throw eligErr;

      for (const row of eligibleRows || []) {
        const amountPaise = Math.round(Number(row.net_amount || 0) * 100);
        if (!Number.isFinite(amountPaise) || amountPaise <= 0) {
          errors.push({ id: row.id, error: "invalid_net_amount" });
          continue;
        }

        const { data: seller } = await supabase
          .from("seller_profiles")
          .select("id, razorpay_account_id, razorpay_onboarding_status")
          .eq("id", row.seller_id)
          .maybeSingle();

        const accountId = seller?.razorpay_account_id;
        if (!accountId) {
          errors.push({
            id: row.id,
            error: "seller_missing_razorpay_account_id",
          });
          continue;
        }

        // Mark processing before transfer to reduce double-pay races
        const { data: locked, error: lockErr } = await supabase
          .from("seller_settlements")
          .update({
            settlement_status: "processing",
            updated_at: new Date().toISOString(),
          })
          .eq("id", row.id)
          .eq("settlement_status", "eligible")
          .is("razorpay_transfer_id", null)
          .select("id");

        if (lockErr || !locked?.length) {
          errors.push({
            id: row.id,
            error: lockErr?.message || "could_not_lock_for_transfer",
          });
          continue;
        }

        const transfer = await createRouteTransfer({
          keyId: creds.keyId,
          keySecret: creds.keySecret,
          accountId,
          amountPaise,
          settlementId: row.id,
          orderId: row.order_id,
        });

        if (!transfer.ok) {
          await supabase
            .from("seller_settlements")
            .update({
              settlement_status: "eligible",
              hold_reason: `Route transfer failed: ${transfer.error}`,
              updated_at: new Date().toISOString(),
            })
            .eq("id", row.id)
            .eq("settlement_status", "processing");

          errors.push({ id: row.id, error: transfer.error });
          continue;
        }

        const { error: settleErr } = await supabase
          .from("seller_settlements")
          .update({
            settlement_status: "settled",
            razorpay_transfer_id: transfer.transferId,
            hold_reason: null,
            settled_at: new Date().toISOString(),
            updated_at: new Date().toISOString(),
          })
          .eq("id", row.id)
          .eq("settlement_status", "processing");

        if (settleErr) {
          errors.push({
            id: row.id,
            error: `transfer_ok_but_db_update_failed:${settleErr.message}:transfer=${transfer.transferId}`,
          });
          continue;
        }

        await supabase.from("audit_log").insert({
          actor_id: null,
          action: "settlement_route_transferred",
          target_type: "seller_settlements",
          target_id: row.id,
          society_id: null,
          metadata: {
            order_id: row.order_id,
            seller_id: row.seller_id,
            net_amount: row.net_amount,
            razorpay_transfer_id: transfer.transferId,
            account_id: accountId,
          },
        });

        transferred++;
      }
    }

    return new Response(
      JSON.stringify({
        processed,
        transferred,
        errors,
        total_pending: (pendingSettlements || []).length,
        route_enabled: routeEnabled,
        message: routeEnabled
          ? `Marked ${processed} eligible; transferred ${transferred} via Razorpay Route.`
          : "Settlements marked eligible only. Enable razorpay_route_enabled + seller linked accounts for payouts.",
      }),
      {
        status: 200,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  } catch (err) {
    return new Response(
      JSON.stringify({ error: (err as Error).message }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
});

import "jsr:@supabase/functions-js/edge-runtime.d.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

/**
 * Public health: status only.
 * Detailed telemetry requires service-role bearer (cron/ops).
 */
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    const authHeader = req.headers.get("Authorization") || "";
    const isService =
      !!serviceKey && authHeader === `Bearer ${serviceKey}`;

    // Cheap DB ping for everyone
    const dbStart = Date.now();
    const { error: dbError } = await supabase
      .from("societies")
      .select("id")
      .limit(1);
    const dbOk = !dbError;
    const dbLatency = Date.now() - dbStart;

    if (!isService) {
      return new Response(
        JSON.stringify({
          status: dbOk ? "healthy" : "degraded",
          checked_at: new Date().toISOString(),
        }),
        {
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        },
      );
    }

    const checks: Record<string, unknown> = {
      db: dbOk ? "ok" : "error",
      db_latency_ms: dbLatency,
    };

    const { count: triggerErrors } = await supabase
      .from("trigger_errors")
      .select("*", { count: "exact", head: true })
      .gte(
        "created_at",
        new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString(),
      );
    checks.trigger_errors_24h = triggerErrors || 0;

    const { data: allSocieties } = await supabase
      .from("societies")
      .select("id")
      .eq("is_active", true);

    const { data: adminedSocieties } = await supabase
      .from("society_admins")
      .select("society_id")
      .is("deactivated_at", null);

    const adminedSet = new Set(
      (adminedSocieties || []).map((a) => a.society_id),
    );
    const orphaned = (allSocieties || []).filter((s) => !adminedSet.has(s.id));
    checks.orphaned_societies = orphaned.length;

    const tables = [
      "profiles",
      "orders",
      "seller_profiles",
      "products",
      "chat_messages",
    ];
    const counts: Record<string, number> = {};
    for (const table of tables) {
      const { count } = await supabase
        .from(table)
        .select("*", { count: "exact", head: true });
      counts[table] = count || 0;
    }
    checks.table_counts = counts;
    checks.auth = "ok";
    checks.status =
      checks.db === "ok" &&
      checks.trigger_errors_24h === 0 &&
      checks.orphaned_societies === 0
        ? "healthy"
        : "degraded";
    checks.checked_at = new Date().toISOString();

    return new Response(JSON.stringify(checks, null, 2), {
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  } catch (err) {
    return new Response(
      JSON.stringify({ status: "error", error: (err as Error).message }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type, x-supabase-client-platform, x-supabase-client-platform-version, x-supabase-client-runtime, x-supabase-client-runtime-version",
};

async function getRazorpayCredentials(supabase: any) {
  // Prefer Deno secrets; fall back to admin_settings for edge service_role reads
  const envKeyId = Deno.env.get("RAZORPAY_KEY_ID") || "";
  const envKeySecret = Deno.env.get("RAZORPAY_KEY_SECRET") || "";
  if (envKeyId && envKeySecret) {
    return { keyId: envKeyId, keySecret: envKeySecret };
  }

  const { data: rows } = await supabase
    .from("admin_settings")
    .select("key, value, is_active")
    .in("key", ["razorpay_key_id", "razorpay_key_secret"]);

  const map: Record<string, string> = {};
  for (const r of rows || []) {
    if (r.value && r.is_active) map[r.key] = r.value;
  }

  return {
    keyId: map.razorpay_key_id || envKeyId,
    keySecret: map.razorpay_key_secret || envKeySecret,
  };
}

function parseNotesOrderIds(notes: any): string[] {
  if (!notes) return [];
  if (notes.order_ids) {
    try {
      const parsed = typeof notes.order_ids === "string" ? JSON.parse(notes.order_ids) : notes.order_ids;
      if (Array.isArray(parsed)) return parsed.map(String);
    } catch { /* fall through */ }
  }
  if (notes.order_id) return [String(notes.order_id)];
  return [];
}

serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response("ok", { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const supabaseServiceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    // Auth: JWT buyer OR service-role (webhook/cron)
    const authHeader = req.headers.get("Authorization") || "";
    const isService = authHeader === `Bearer ${supabaseServiceKey}`;
    let callerUserId: string | null = null;

    if (!isService) {
      const { withAuth } = await import("../_shared/auth.ts");
      const authResult = await withAuth(req, corsHeaders);
      if (authResult instanceof Response) return authResult;
      callerUserId = authResult.userId;
    }

    const body = await req.json().catch(() => null);
    if (!body) {
      return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { razorpay_payment_id, razorpay_order_id } = body;
    let order_ids: string[] = Array.isArray(body.order_ids) ? body.order_ids.map(String) : [];
    const source = body.source || (isService ? "service" : "client_confirm");

    if (
      (!razorpay_payment_id && !razorpay_order_id) ||
      !order_ids ||
      order_ids.length === 0
    ) {
      return new Response(
        JSON.stringify({ error: "Missing razorpay_payment_id/razorpay_order_id or order_ids" }),
        { status: 400, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    const creds = await getRazorpayCredentials(supabase);
    if (!creds.keyId || !creds.keySecret) {
      return new Response(JSON.stringify({ error: "Payment gateway not configured" }), {
        status: 503,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const authBasic = "Basic " + btoa(`${creds.keyId}:${creds.keySecret}`);

    // Load seed orders, then expand ALL siblings via checkout_group_id BEFORE amount check
    const { data: seedOrders, error: seedErr } = await supabase
      .from("orders")
      .select("id, buyer_id, seller_id, total_amount, society_id, status, payment_status, razorpay_order_id, platform_fee, net_amount, loyalty_reservation_id, loyalty_discount_amount, loyalty_points_redeemed, checkout_group_id")
      .in("id", order_ids);

    if (seedErr || !seedOrders || seedOrders.length === 0) {
      return new Response(JSON.stringify({ error: "One or more orders not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const groupIds = Array.from(
      new Set(
        seedOrders
          .map((o: any) => o.checkout_group_id)
          .filter((id: string | null | undefined) => !!id),
      ),
    ) as string[];

    let orders = seedOrders as any[];
    if (groupIds.length > 0) {
      const { data: siblings, error: sibErr } = await supabase
        .from("orders")
        .select("id, buyer_id, seller_id, total_amount, society_id, status, payment_status, razorpay_order_id, platform_fee, net_amount, loyalty_reservation_id, loyalty_discount_amount, loyalty_points_redeemed, checkout_group_id")
        .in("checkout_group_id", groupIds);

      if (sibErr || !siblings?.length) {
        return new Response(JSON.stringify({ error: "Failed to resolve checkout group siblings" }), {
          status: 500,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      orders = siblings;
      order_ids = siblings.map((o: any) => o.id);
      console.log(`[confirm] expanded checkout_group siblings → ${order_ids.length} orders`, groupIds);
    } else if (seedOrders.length !== order_ids.length) {
      return new Response(JSON.stringify({ error: "One or more orders not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (callerUserId) {
      const unauthorized = orders.some((o: any) => o.buyer_id !== callerUserId);
      if (unauthorized) {
        return new Response(JSON.stringify({ error: "Forbidden" }), {
          status: 403,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
    }

    const expectedPaise = Math.round(
      orders.reduce((sum: number, o: any) => sum + Number(o.total_amount || 0), 0) * 100
    );
    const expectedRzpOrderId = orders[0]?.razorpay_order_id || razorpay_order_id;

    let verifiedPaymentId = razorpay_payment_id;
    let paymentEntity: any = null;

    if (razorpay_payment_id && razorpay_payment_id !== "reconciled") {
      const rzpResponse = await fetch(
        `https://api.razorpay.com/v1/payments/${razorpay_payment_id}`,
        { headers: { Authorization: authBasic } }
      );
      if (!rzpResponse.ok) {
        return new Response(JSON.stringify({ error: "Payment verification failed" }), {
          status: 502,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      paymentEntity = await rzpResponse.json();
      if (paymentEntity.status !== "captured" && paymentEntity.status !== "authorized") {
        return new Response(
          JSON.stringify({ error: "Payment not confirmed", status: paymentEntity.status }),
          { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
    } else if (expectedRzpOrderId) {
      const rzpResponse = await fetch(
        `https://api.razorpay.com/v1/orders/${expectedRzpOrderId}/payments`,
        { headers: { Authorization: authBasic } }
      );
      if (!rzpResponse.ok) {
        return new Response(JSON.stringify({ error: "Payment verification failed" }), {
          status: 502,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      const data = await rzpResponse.json();
      const items = data.items || data;
      paymentEntity = Array.isArray(items)
        ? items.find((p: any) => p.status === "captured" || p.status === "authorized")
        : null;
      if (!paymentEntity) {
        return new Response(
          JSON.stringify({ error: "No captured payment found for this order" }),
          { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
        );
      }
      verifiedPaymentId = paymentEntity.id;
    } else {
      return new Response(JSON.stringify({ error: "Cannot verify payment without ID" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Amount binding against FULL sibling set (allow 1 paise rounding)
    const paidPaise = Number(paymentEntity.amount || 0);
    if (Math.abs(paidPaise - expectedPaise) > 1) {
      console.error(`[confirm] amount mismatch paid=${paidPaise} expected=${expectedPaise} orders=${order_ids.length}`);
      return new Response(
        JSON.stringify({ error: "Payment amount does not match order total" }),
        { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Bind Razorpay order id when present on payment
    if (paymentEntity.order_id && expectedRzpOrderId && paymentEntity.order_id !== expectedRzpOrderId) {
      console.error(`[confirm] razorpay_order_id mismatch`);
      return new Response(
        JSON.stringify({ error: "Payment does not belong to these orders" }),
        { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
      );
    }

    // Bind notes order_ids when present — every DB sibling must appear in notes (or notes subset of siblings)
    const noteIds = parseNotesOrderIds(paymentEntity.notes);
    if (noteIds.length > 0) {
      const missingFromNotes = order_ids.filter((id: string) => !noteIds.includes(id));
      const extraInNotes = noteIds.filter((id: string) => !order_ids.includes(id));
      if (missingFromNotes.length > 0 || extraInNotes.length > 0) {
        // Allow notes to be a subset only if we expanded from a partial client list;
        // after expansion, notes and siblings should match.
        if (missingFromNotes.length > 0) {
          return new Response(
            JSON.stringify({
              error: "Payment notes do not include all checkout group orders",
              missing: missingFromNotes,
            }),
            { status: 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
          );
        }
      }
    }

    const results: { id: string; success: boolean; skipped?: boolean; resurrected?: boolean; error?: string }[] = [];
    const now = new Date().toISOString();
    let hardFailure = false;

    for (const orderData of orders) {
      const orderId = orderData.id;

      if (orderData.payment_status === "paid") {
        results.push({ id: orderId, success: true, skipped: true });
        continue;
      }

      const { error: payRecErr } = await supabase.from("payment_records").upsert(
        {
          order_id: orderId,
          buyer_id: orderData.buyer_id,
          seller_id: orderData.seller_id,
          amount: orderData.total_amount,
          platform_fee: Number(orderData.platform_fee || 0),
          net_amount: Number(
            orderData.net_amount != null
              ? orderData.net_amount
              : Number(orderData.total_amount || 0) - Number(orderData.platform_fee || 0),
          ),
          razorpay_payment_id: verifiedPaymentId,
          payment_status: "paid",
          payment_method: "online",
          transaction_reference: verifiedPaymentId,
          payment_collection: "direct",
          payment_mode: "online",
          society_id: orderData.society_id,
        },
        { onConflict: "order_id", ignoreDuplicates: false }
      );
      if (payRecErr) {
        console.error("payment_records upsert failed for order", orderId, payRecErr);
        results.push({ id: orderId, success: false, error: payRecErr.message });
        hardFailure = true;
        continue;
      }

      // Leave auto_cancel_at alone — DB trigger stamps the 5-minute
      // seller-acceptance deadline when status becomes `placed`.
      const { data: updated, error: updateErr } = await supabase
        .from("orders")
        .update({
          status: "placed",
          payment_status: "paid",
          razorpay_payment_id: verifiedPaymentId,
          updated_at: now,
        })
        .eq("id", orderId)
        .in("status", ["payment_pending", "placed"])
        .in("payment_status", ["pending"])
        .select("id");

      if (updateErr) {
        results.push({ id: orderId, success: false, error: updateErr.message });
        hardFailure = true;
        continue;
      }

      if (!updated || updated.length === 0) {
        // Paid-after-cancel resurrection: only if still pending pay + cancelled.
        // MUST re-hold stock atomically via RPC — never paid with free stock.
        const { data: cancelledOrder } = await supabase
          .from("orders")
          .select("id")
          .eq("id", orderId)
          .eq("status", "cancelled")
          .eq("payment_status", "pending")
          .maybeSingle();

        if (cancelledOrder) {
          const { data: resurrectData, error: resurrectErr } = await supabase.rpc(
            "resurrect_cancelled_order_after_payment",
            {
              p_order_id: orderId,
              p_razorpay_payment_id: verifiedPaymentId,
            },
          );

          if (resurrectErr || resurrectData?.success === false) {
            console.error("[confirm] resurrection failed — leave for refund path", orderId, resurrectErr || resurrectData);
            results.push({
              id: orderId,
              success: false,
              error: resurrectErr?.message || resurrectData?.error || "resurrect_failed",
            });
            hardFailure = true;
            continue;
          }

          results.push({ id: orderId, success: true, resurrected: true });
          continue;
        }

        results.push({ id: orderId, success: true, skipped: true });
        continue;
      }

      results.push({ id: orderId, success: true });
    }

    // After any child failure post-capture: do NOT return silent success
    const successCount = results.filter((r) => r.success && !r.skipped).length;
    let allOk = results.every((r) => r.success) && !hardFailure;

    // Stamp checkout_group payment header when children share a group
    if (groupIds.length > 0 && (allOk || successCount > 0)) {
      for (const groupId of groupIds) {
        const { error: stampErr } = await supabase.rpc("stamp_checkout_group_capture", {
          _group_id: groupId,
          _razorpay_payment_id: verifiedPaymentId,
          _razorpay_order_id: expectedRzpOrderId || razorpay_order_id || null,
        });
        if (stampErr) {
          console.error("[confirm] stamp_checkout_group_capture failed", groupId, stampErr);
          const { error: groupErr } = await supabase
            .from("checkout_groups")
            .update({
              payment_status: "paid",
              razorpay_order_id: expectedRzpOrderId || razorpay_order_id || null,
              razorpay_payment_id: verifiedPaymentId,
              updated_at: now,
            })
            .eq("id", groupId);
          if (groupErr) {
            console.error("[confirm] checkout_groups stamp failed", groupId, groupErr);
          } else {
            try {
              await supabase.rpc("refresh_checkout_group_totals", { _group_id: groupId });
            } catch (refreshErr) {
              console.warn("[confirm] refresh_checkout_group_totals failed", refreshErr);
            }
          }
        }
      }
    }

    // Fail-closed: never success:true if wallet/loyalty commit fails
    let loyaltyCommit: unknown = null;
    let walletCommit: unknown = null;
    let commitFailed = false;

    if (allOk || successCount > 0) {
      try {
        const { data: commitData, error: commitErr } = await supabase.rpc(
          "commit_loyalty_for_orders",
          { _order_ids: order_ids },
        );
        if (commitErr) {
          console.error("[confirm] loyalty commit failed", commitErr);
          commitFailed = true;
        } else {
          loyaltyCommit = commitData;
        }
      } catch (loyaltyErr) {
        console.error("[confirm] loyalty commit exception", loyaltyErr);
        commitFailed = true;
      }

      try {
        const { data: walletData, error: walletErr } = await supabase.rpc(
          "commit_wallet_for_orders",
          { _order_ids: order_ids },
        );
        if (walletErr) {
          console.error("[confirm] wallet commit failed", walletErr);
          commitFailed = true;
        } else {
          walletCommit = walletData;
        }
      } catch (walletEx) {
        console.error("[confirm] wallet commit exception", walletEx);
        commitFailed = true;
      }
    }

    if (commitFailed) {
      allOk = false;
    }

    if (allOk && successCount > 0) {
      setTimeout(() => {
        fetch(`${supabaseUrl}/functions/v1/process-notification-queue`, {
          method: "POST",
          headers: {
            Authorization: `Bearer ${supabaseServiceKey}`,
            "Content-Type": "application/json",
          },
          body: "{}",
        }).catch(() => {});
      }, 2000);
    }

    return new Response(
      JSON.stringify({
        success: allOk,
        confirmed: successCount,
        results,
        loyalty: loyaltyCommit,
        wallet: walletCommit,
        commit_failed: commitFailed,
        source,
        order_ids,
      }),
      { status: allOk ? 200 : 409, headers: { ...corsHeaders, "Content-Type": "application/json" } }
    );
  } catch (error) {
    console.error("confirm-razorpay-payment error:", error);
    return new Response(JSON.stringify({ error: String(error) }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

// Refund Processor Edge Function
// Executes real Razorpay refunds — never simulates success.
// P4: partial refunds against shared checkout-group captures.
import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers": "authorization, x-client-info, apikey, content-type",
  "Access-Control-Allow-Methods": "POST, OPTIONS",
};

interface ProcessRequest {
  refund_id: string;
}

async function getRazorpayKeys(supabase: any): Promise<{ keyId: string; keySecret: string } | null> {
  const { data: settings } = await supabase
    .from("admin_settings")
    .select("key, value, is_active")
    .in("key", ["razorpay_key_id", "razorpay_key_secret"]);

  const map: Record<string, string> = {};
  for (const r of settings || []) {
    if (r.value && r.is_active) map[r.key] = r.value;
  }

  const keyId = map.razorpay_key_id || Deno.env.get("RAZORPAY_KEY_ID") || "";
  const keySecret = map.razorpay_key_secret || Deno.env.get("RAZORPAY_KEY_SECRET") || "";
  if (!keyId || !keySecret) return null;
  return { keyId, keySecret };
}

async function fetchPaymentRefundable(
  keys: { keyId: string; keySecret: string },
  paymentId: string,
): Promise<{ amountPaise: number; amountRefundedPaise: number; status: string } | null> {
  const auth = "Basic " + btoa(`${keys.keyId}:${keys.keySecret}`);
  const res = await fetch(`https://api.razorpay.com/v1/payments/${paymentId}`, {
    headers: { Authorization: auth },
  });
  const raw = await res.json().catch(() => ({}));
  if (!res.ok) {
    console.error("[refund-processor] payment fetch failed", paymentId, raw);
    return null;
  }
  return {
    amountPaise: Number(raw.amount || 0),
    amountRefundedPaise: Number(raw.amount_refunded || 0),
    status: String(raw.status || ""),
  };
}

async function callRazorpayRefund(
  keys: { keyId: string; keySecret: string },
  paymentId: string,
  amountRupees: number,
  refundId: string,
  opts?: { reverseAll?: boolean },
): Promise<{ ok: boolean; reference: string; status: string; raw: any; error?: string }> {
  const amountPaise = Math.round(Number(amountRupees) * 100);
  const auth = "Basic " + btoa(`${keys.keyId}:${keys.keySecret}`);

  const body: Record<string, unknown> = {
    amount: amountPaise,
    notes: { refund_request_id: refundId, sociva_partial: true },
  };
  // Route: reverse linked transfers when this refund covers the full remaining capture
  if (opts?.reverseAll) {
    body.reverse_all = 1;
  }

  const res = await fetch(`https://api.razorpay.com/v1/payments/${paymentId}/refund`, {
    method: "POST",
    headers: {
      Authorization: auth,
      "Content-Type": "application/json",
      "X-Razorpay-Idempotency-Key": `refund-${refundId}`,
    },
    body: JSON.stringify(body),
  });

  const raw = await res.json().catch(() => ({}));
  if (!res.ok) {
    return {
      ok: false,
      reference: "",
      status: "failed",
      raw,
      error: raw?.error?.description || raw?.error?.reason || `HTTP ${res.status}`,
    };
  }

  return {
    ok: true,
    reference: raw.id || `rzp_rfnd_${refundId.slice(0, 8)}`,
    status: raw.status || "processed",
    raw,
  };
}

Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;
    const supabase = createClient(supabaseUrl, serviceKey);

    const authHeader = req.headers.get("Authorization") || "";
    const isService = authHeader === `Bearer ${serviceKey}`;
    const isCron = req.headers.get("x-cron-secret") === Deno.env.get("CRON_SECRET");
    let callerUserId: string | null = null;

    if (!isService && !isCron) {
      const userClient = createClient(supabaseUrl, Deno.env.get("SUPABASE_ANON_KEY")!, {
        global: { headers: { Authorization: authHeader } },
      });
      const { data: { user } } = await userClient.auth.getUser();
      if (!user) {
        return new Response(JSON.stringify({ error: "Unauthorized" }), {
          status: 401,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      callerUserId = user.id;
    }

    const body = (await req.json().catch(() => ({}))) as ProcessRequest;
    if (!body.refund_id) {
      return new Response(JSON.stringify({ error: "refund_id required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const { data: refund, error: fetchErr } = await supabase
      .from("refund_requests")
      .select("id, refund_state, amount, order_id, buyer_id, refund_destination, wallet_credit_amount")
      .eq("id", body.refund_id)
      .single();

    if (fetchErr || !refund) {
      return new Response(JSON.stringify({ error: "Refund not found" }), {
        status: 404,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // Ownership: seller of order, admin, or service/cron
    if (callerUserId) {
      const { data: order } = await supabase
        .from("orders")
        .select("seller_id")
        .eq("id", refund.order_id)
        .single();

      const { data: sellerProfile } = order?.seller_id
        ? await supabase
            .from("seller_profiles")
            .select("user_id")
            .eq("id", order.seller_id)
            .maybeSingle()
        : { data: null };

      const { data: isAdmin } = await supabase.rpc("is_admin", { _user_id: callerUserId });
      const isSellerOwner = sellerProfile?.user_id === callerUserId;

      if (!isSellerOwner && !isAdmin) {
        return new Response(JSON.stringify({ error: "Forbidden" }), {
          status: 403,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
    }

    if (refund.refund_state === "refund_completed" || refund.refund_state === "settled") {
      return new Response(
        JSON.stringify({
          ok: true,
          skipped: true,
          state: refund.refund_state,
          message: `Refund already completed`,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    if (refund.refund_state !== "approved") {
      return new Response(
        JSON.stringify({
          ok: true,
          skipped: true,
          state: refund.refund_state,
          message: `Refund already in state ${refund.refund_state}`,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // Sociva Credit path: skip Razorpay, credit wallet + complete
    const destination = (refund as { refund_destination?: string }).refund_destination || "original_payment";
    if (destination === "wallet") {
      const { data: walletDone, error: walletErr } = await supabase.rpc("complete_wallet_refund", {
        p_refund_id: refund.id,
      });
      if (walletErr) {
        console.error("[refund-processor] wallet refund failed", walletErr);
        await supabase.rpc("fail_refund", {
          p_refund_id: refund.id,
          p_reason: walletErr.message || "Wallet credit failed",
        });
        return new Response(
          JSON.stringify({ ok: false, state: "refund_failed", error: walletErr.message, destination: "wallet" }),
          { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
        );
      }
      console.log(`[refund-processor] completed wallet refund ${refund.id}`);
      return new Response(
        JSON.stringify({
          ok: true,
          state: "refund_completed",
          destination: "wallet",
          gateway_ref: walletDone?.gateway_refund_id || null,
          simulated: false,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const keys = await getRazorpayKeys(supabase);
    if (!keys) {
      return new Response(
        JSON.stringify({
          error: "Refund gateway not configured. Set Razorpay keys before processing refunds.",
        }),
        { status: 503, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // P4: resolve payment from order OR checkout_group; amount = child share
    const { data: gwCtx, error: ctxErr } = await supabase.rpc("resolve_refund_gateway_context", {
      p_refund_id: refund.id,
    });
    if (ctxErr) {
      console.error("[refund-processor] resolve context failed", ctxErr);
    }
    const ctx = (gwCtx || {}) as {
      ok?: boolean;
      razorpay_payment_id?: string;
      amount?: number;
      is_partial?: boolean;
      checkout_group_id?: string;
    };

    let paymentId = ctx.razorpay_payment_id || null;
    if (!paymentId) {
      const { data: orderPay } = await supabase
        .from("orders")
        .select("razorpay_payment_id, checkout_group_id")
        .eq("id", refund.order_id)
        .single();
      paymentId = orderPay?.razorpay_payment_id || null;
      if (!paymentId && orderPay?.checkout_group_id) {
        const { data: group } = await supabase
          .from("checkout_groups")
          .select("razorpay_payment_id")
          .eq("id", orderPay.checkout_group_id)
          .maybeSingle();
        paymentId = group?.razorpay_payment_id || null;
      }
    }

    if (!paymentId) {
      // Audit: no razorpay_payment_id → route to wallet destination
      console.warn(`[refund-processor] no razorpay_payment_id for ${refund.id} — routing to wallet`);
      await supabase
        .from("refund_requests")
        .update({
          refund_destination: "wallet",
          wallet_credit_amount: refund.amount,
          updated_at: new Date().toISOString(),
        })
        .eq("id", refund.id)
        .eq("refund_state", "approved");

      const { data: walletDone, error: walletErr } = await supabase.rpc("complete_wallet_refund", {
        p_refund_id: refund.id,
      });
      if (walletErr) {
        console.error("[refund-processor] wallet fallback failed", walletErr);
        await supabase.rpc("fail_refund", {
          p_refund_id: refund.id,
          p_reason: walletErr.message || "Wallet credit failed (no razorpay_payment_id)",
        });
        return new Response(
          JSON.stringify({ ok: false, state: "refund_failed", error: walletErr.message, destination: "wallet" }),
          { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
        );
      }
      return new Response(
        JSON.stringify({
          ok: true,
          state: "refund_completed",
          destination: "wallet",
          gateway_ref: walletDone?.gateway_refund_id || null,
          routed_from: "missing_razorpay_payment_id",
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const idempotencyKey = `refund-${refund.id}-attempt-1`;
    const { error: initErr } = await supabase.rpc("initiate_refund", {
      p_refund_id: refund.id,
      p_idempotency_key: idempotencyKey,
    });
    if (initErr) {
      console.error("[refund-processor] initiate failed", initErr);
      return new Response(JSON.stringify({ error: initErr.message }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    // P0: ignore client-stored refund.amount — recompute from order server-side only
    let gatewayRefundAmount = Number(ctx.amount);
    if (!Number.isFinite(gatewayRefundAmount) || gatewayRefundAmount <= 0) {
      const { data: recomputed } = await supabase.rpc("compute_child_gateway_refund_amount", {
        _order_id: refund.order_id,
      });
      gatewayRefundAmount = Number(recomputed);
    }
    if (!Number.isFinite(gatewayRefundAmount) || gatewayRefundAmount <= 0) {
      await supabase.rpc("fail_refund", {
        p_refund_id: refund.id,
        p_reason: "Server could not compute refund amount from order",
      });
      return new Response(
        JSON.stringify({ ok: false, state: "refund_failed", error: "uncomputable_refund_amount" }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    // Cap against live Razorpay remaining (partial refunds must not overshoot)
    const live = await fetchPaymentRefundable(keys, paymentId);
    if (live) {
      const remainingRupees = Math.max(0, (live.amountPaise - live.amountRefundedPaise) / 100);
      if (remainingRupees <= 0) {
        // Already fully refunded at gateway — complete locally idempotently
        const { error: doneErr } = await supabase.rpc("complete_refund", {
          p_refund_id: refund.id,
          p_gateway_ref: `already-refunded-${paymentId}`,
          p_gateway_status: "already_refunded",
        });
        if (doneErr) {
          console.error("[refund-processor] complete after already-refunded failed", doneErr);
          return new Response(JSON.stringify({ error: doneErr.message }), {
            status: 500,
            headers: { ...corsHeaders, "Content-Type": "application/json" },
          });
        }
        return new Response(
          JSON.stringify({
            ok: true,
            state: "refund_completed",
            gateway_ref: `already-refunded-${paymentId}`,
            simulated: false,
            note: "payment already fully refunded at gateway",
          }),
          { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
        );
      }
      gatewayRefundAmount = Math.min(gatewayRefundAmount, remainingRupees);
    }

    // Round to paise-safe 2dp
    gatewayRefundAmount = Math.round(gatewayRefundAmount * 100) / 100;
    if (gatewayRefundAmount < 0.01) {
      await supabase.rpc("fail_refund", {
        p_refund_id: refund.id,
        p_reason: "Computed gateway refund amount is zero",
      });
      return new Response(
        JSON.stringify({ ok: false, state: "refund_failed", error: "zero_refund_amount" }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const remainingAfter = live
      ? (live.amountPaise - live.amountRefundedPaise) / 100 - gatewayRefundAmount
      : null;
    const reverseAll = remainingAfter !== null && remainingAfter < 0.01;

    const gw = await callRazorpayRefund(keys, paymentId, gatewayRefundAmount, refund.id, {
      reverseAll,
    });

    if (gw.ok) {
      const { error: doneErr } = await supabase.rpc("complete_refund", {
        p_refund_id: refund.id,
        p_gateway_ref: gw.reference,
        p_gateway_status: gw.status,
      });
      if (doneErr) {
        console.error("[refund-processor] complete failed", doneErr);
        return new Response(JSON.stringify({ error: doneErr.message }), {
          status: 500,
          headers: { ...corsHeaders, "Content-Type": "application/json" },
        });
      }
      console.log(
        `[refund-processor] completed refund ${refund.id} ref=${gw.reference} amount=${gatewayRefundAmount} partial=${ctx.is_partial} reverse_all=${reverseAll}`,
      );
      return new Response(
        JSON.stringify({
          ok: true,
          state: "refund_completed",
          gateway_ref: gw.reference,
          amount: gatewayRefundAmount,
          partial: !!ctx.is_partial,
          reverse_all: reverseAll,
          simulated: false,
        }),
        { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    await supabase.rpc("fail_refund", {
      p_refund_id: refund.id,
      p_reason: gw.error || "Gateway error",
    });
    return new Response(
      JSON.stringify({ ok: false, state: "refund_failed", error: gw.error, simulated: false }),
      { status: 200, headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (err: any) {
    console.error("[refund-processor] error", err);
    return new Response(JSON.stringify({ error: err.message || "Internal error" }), {
      status: 500,
      headers: { ...corsHeaders, "Content-Type": "application/json" },
    });
  }
});

import { serve } from "https://deno.land/std@0.168.0/http/server.ts";
import { createClient } from "https://esm.sh/@supabase/supabase-js@2";
import { crypto } from "https://deno.land/std@0.168.0/crypto/mod.ts";

const corsHeaders = {
  'Access-Control-Allow-Origin': '*',
  'Access-Control-Allow-Headers': 'authorization, x-client-info, apikey, content-type, x-razorpay-signature',
};

async function getRazorpayWebhookSecret(supabase: any): Promise<string | null> {
  // Prefer dedicated webhook secret — API key secret is NOT the webhook HMAC secret.
  // Fail closed: do not fall back to razorpay_key_secret (wrong secret → false accepts / rejects).
  const { data: settings } = await supabase
    .from('admin_settings')
    .select('key, value, is_active')
    .eq('key', 'razorpay_webhook_secret');

  const row = (settings || []).find((r: any) => r.value && r.is_active);
  if (row?.value) return row.value;

  const envWebhook = Deno.env.get('RAZORPAY_WEBHOOK_SECRET');
  if (envWebhook) return envWebhook;

  console.error(
    '[razorpay-webhook] razorpay_webhook_secret missing or inactive — paste Webhook Secret from Razorpay Dashboard → Webhooks. Refusing to verify with API key secret.',
  );
  return null;
}

async function verifySignature(body: string, signature: string, secret: string): Promise<boolean> {
  try {
    const encoder = new TextEncoder();
    const key = await crypto.subtle.importKey(
      'raw',
      encoder.encode(secret),
      { name: 'HMAC', hash: 'SHA-256' },
      false,
      ['sign']
    );

    const signatureBuffer = await crypto.subtle.sign(
      'HMAC',
      key,
      encoder.encode(body)
    );

    const expectedBytes = new Uint8Array(signatureBuffer);

    const sigBytes = new Uint8Array(signature.length / 2);
    for (let i = 0; i < signature.length; i += 2) {
      sigBytes[i / 2] = parseInt(signature.substring(i, i + 2), 16);
    }

    if (expectedBytes.length !== sigBytes.length) return false;

    let diff = 0;
    for (let i = 0; i < expectedBytes.length; i++) {
      diff |= expectedBytes[i] ^ sigBytes[i];
    }
    return diff === 0;
  } catch (error) {
    console.error('Signature verification error:', error);
    return false;
  }
}

/** Parse order IDs from payment notes — supports multi-vendor (order_ids) and single (order_id) */
function resolveOrderIds(notes: any): string[] {
  if (notes?.order_ids) {
    try {
      const parsed = typeof notes.order_ids === 'string'
        ? JSON.parse(notes.order_ids)
        : notes.order_ids;
      if (Array.isArray(parsed) && parsed.length > 0) return parsed.map(String);
    } catch { /* fall through */ }
  }
  if (notes?.order_id) return [String(notes.order_id)];
  return [];
}

serve(async (req) => {
  if (req.method === 'OPTIONS') {
    return new Response('ok', { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get('SUPABASE_URL')!;
    const supabaseServiceKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')!;
    const supabase = createClient(supabaseUrl, supabaseServiceKey);

    const body = await req.text();
    const signature = req.headers.get('x-razorpay-signature');

    const webhookSecret = await getRazorpayWebhookSecret(supabase);
    if (!webhookSecret) {
      console.error('Razorpay webhook secret not configured');
      return new Response(
        JSON.stringify({ error: 'Payment gateway not configured' }),
        { status: 503, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    if (!signature) {
      console.error('Missing x-razorpay-signature header');
      return new Response(
        JSON.stringify({ error: 'Missing signature' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const isValid = await verifySignature(body, signature, webhookSecret);
    if (!isValid) {
      console.error('Invalid webhook signature');
      return new Response(
        JSON.stringify({ error: 'Invalid signature' }),
        { status: 401, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
      );
    }

    const payload = JSON.parse(body);
    const event = payload.event;
    const paymentEntity = payload.payload?.payment?.entity;
    const refundEntity = payload.payload?.refund?.entity;

    const webhookOrderIds = resolveOrderIds(paymentEntity?.notes || refundEntity?.notes);
    console.log(`[razorpay-webhook] event=${event}, razorpay_payment_id=${paymentEntity?.id || refundEntity?.payment_id}, order_ids=${JSON.stringify(webhookOrderIds)}, razorpay_order_id=${paymentEntity?.order_id || 'none'}`);

    if (event === 'payment.captured') {
      const razorpayPaymentId = paymentEntity.id;
      const allOrderIds = resolveOrderIds(paymentEntity.notes);

      if (allOrderIds.length === 0) {
        console.error('No order IDs found in payment notes — acknowledging to stop retries');
        return new Response(
          JSON.stringify({ acknowledged: true, skipped: 'no_order_id' }),
          { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
        );
      }

      console.log(`Payment ${razorpayPaymentId} captured for ${allOrderIds.length} order(s) — confirming as ONE group:`, allOrderIds);

      // P0: ONE confirm call with FULL order_ids — never one-at-a-time amount binding
      const confirmRes = await fetch(`${supabaseUrl}/functions/v1/confirm-razorpay-payment`, {
        method: 'POST',
        headers: {
          Authorization: `Bearer ${supabaseServiceKey}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          razorpay_payment_id: razorpayPaymentId,
          razorpay_order_id: paymentEntity.order_id || null,
          order_ids: allOrderIds,
          source: 'webhook',
        }),
      });

      if (!confirmRes.ok) {
        const errText = await confirmRes.text();
        console.error(`[razorpay-webhook] confirm failed for group:`, errText);
        return new Response(
          JSON.stringify({
            error: 'confirm_failed',
            status: confirmRes.status,
            body: errText.slice(0, 800),
            order_ids: allOrderIds,
          }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
        );
      }

      const confirmBody = await confirmRes.json().catch(() => ({}));
      // Fail closed: confirm may return 200 with success:false
      if (confirmBody?.success === false) {
        console.error('[razorpay-webhook] confirm returned success:false', confirmBody);
        return new Response(
          JSON.stringify({ error: 'confirm_incomplete', result: confirmBody }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
        );
      }

      console.log(`[razorpay-webhook] ✅ group confirmed razorpay_payment_id=${razorpayPaymentId} orders=${allOrderIds.length}`);
    } else if (event === 'payment.failed') {
      const allOrderIds = resolveOrderIds(paymentEntity.notes);

      for (const orderId of allOrderIds) {
        console.log(`Payment failed for order ${orderId}`);

        // Guard: never overwrite a 'paid' status with 'failed'
        await supabase
          .from('orders')
          .update({ payment_status: 'failed' })
          .eq('id', orderId)
          .neq('payment_status', 'paid');

        await supabase
          .from('payment_records')
          .update({ payment_status: 'failed' })
          .eq('order_id', orderId)
          .neq('payment_status', 'paid');
      }
    } else if (event === 'refund.created' || event === 'refund.processed') {
      // P0: NEVER raw-update orders.payment_status='refunded'.
      // Drive idempotent complete_refund / reconcile by gateway_refund_id only.
      const gatewayRefundId = refundEntity?.id as string | undefined;
      const gatewayStatus = refundEntity?.status || event;
      const paymentId = refundEntity?.payment_id || paymentEntity?.id;

      if (!gatewayRefundId) {
        console.warn('[razorpay-webhook] refund event missing refund.id — ack without mutating orders');
        return new Response(
          JSON.stringify({ acknowledged: true, skipped: 'no_gateway_refund_id' }),
          { status: 200, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
        );
      }

      const { data: reconcileResult, error: reconcileErr } = await supabase.rpc(
        'complete_refund_by_gateway_id',
        {
          p_gateway_refund_id: gatewayRefundId,
          p_gateway_status: gatewayStatus,
          p_razorpay_payment_id: paymentId || null,
        },
      );

      if (reconcileErr) {
        console.error('[razorpay-webhook] complete_refund_by_gateway_id failed', reconcileErr);
        // Do not ACK success — Razorpay should retry; never leave money state via raw UPDATE
        return new Response(
          JSON.stringify({ error: 'refund_reconcile_failed', detail: reconcileErr.message }),
          { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } },
        );
      }

      console.log('[razorpay-webhook] refund reconciled', gatewayRefundId, reconcileResult);
    }

    return new Response(
      JSON.stringify({ received: true }),
      { headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  } catch (error) {
    console.error('Webhook error:', error);
    return new Response(
      JSON.stringify({ error: 'Internal server error' }),
      { status: 500, headers: { ...corsHeaders, 'Content-Type': 'application/json' } }
    );
  }
});

import { createClient } from "https://esm.sh/@supabase/supabase-js@2.93.3";

const corsHeaders = {
  "Access-Control-Allow-Origin": "*",
  "Access-Control-Allow-Headers":
    "authorization, x-client-info, apikey, content-type",
};

/**
 * Per-order acceptance expiry worker.
 * Invoked once when an order becomes `placed`. Reads fire_at from
 * order_acceptance_expiry (ignores client clock), waits until due, then
 * cancels that order by id via expire_unaccepted_order (O(1)).
 */
Deno.serve(async (req) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    // P0: service_role (or CRON_SECRET) only — never accept anon JWT
    const authHeader = req.headers.get("Authorization") || "";
    const token = authHeader.replace(/^Bearer\s+/i, "");
    const allowed =
      token === serviceKey ||
      req.headers.get("x-cron-secret") === Deno.env.get("CRON_SECRET");

    if (!allowed) {
      return new Response(JSON.stringify({ error: "Unauthorized" }), {
        status: 401,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const body = await req.json().catch(() => ({}));
    const orderId = body?.order_id as string | undefined;
    if (!orderId) {
      return new Response(JSON.stringify({ error: "order_id required" }), {
        status: 400,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const supabase = createClient(supabaseUrl, serviceKey);

    const { data: timer, error: timerErr } = await supabase
      .from("order_acceptance_expiry")
      .select("order_id, fire_at")
      .eq("order_id", orderId)
      .maybeSingle();

    if (timerErr) {
      console.error("[expire-unaccepted-order] timer lookup failed", timerErr);
      return new Response(JSON.stringify({ error: timerErr.message }), {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    if (!timer) {
      // Already accepted/cancelled/cleared — nothing to do
      return new Response(
        JSON.stringify({ ok: true, skipped: true, reason: "no_timer" }),
        { headers: { ...corsHeaders, "Content-Type": "application/json" } },
      );
    }

    const fireAtMs = new Date(timer.fire_at).getTime();
    const delayMs = Math.max(0, fireAtMs - Date.now());
    // Cap slightly above 5m so a slow schedule still waits out the SLA
    const cappedDelay = Math.min(delayMs, 6 * 60 * 1000);

    const runExpire = async () => {
      // Re-check timer still present (seller may have accepted while waiting)
      const { data: still } = await supabase
        .from("order_acceptance_expiry")
        .select("order_id, fire_at")
        .eq("order_id", orderId)
        .maybeSingle();

      if (!still) {
        return { cancelled: false, reason: "timer_cleared" };
      }

      const due = new Date(still.fire_at).getTime() <= Date.now() + 250;
      if (!due) {
        return { cancelled: false, reason: "not_yet_due" };
      }

      const { data, error } = await supabase.rpc("expire_unaccepted_order", {
        _order_id: orderId,
      });

      if (error) {
        console.error("[expire-unaccepted-order] rpc failed", orderId, error);
        return { cancelled: false, reason: error.message };
      }
      return data;
    };

    if (cappedDelay === 0) {
      const result = await runExpire();
      return new Response(JSON.stringify({ ok: true, result }), {
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      });
    }

    const task = new Promise<void>((resolve) => {
      setTimeout(async () => {
        try {
          const result = await runExpire();
          console.log("[expire-unaccepted-order] fired", orderId, result);
        } catch (e) {
          console.error("[expire-unaccepted-order] wait task failed", orderId, e);
        } finally {
          resolve();
        }
      }, cappedDelay);
    });

    const runtime = (globalThis as unknown as { EdgeRuntime?: { waitUntil: (p: Promise<unknown>) => void } }).EdgeRuntime;
    if (runtime?.waitUntil) {
      runtime.waitUntil(task);
    } else {
      // Local / no waitUntil: still await so the cancel happens
      await task;
    }

    return new Response(
      JSON.stringify({
        ok: true,
        scheduled: true,
        order_id: orderId,
        delay_ms: cappedDelay,
        fire_at: timer.fire_at,
      }),
      { headers: { ...corsHeaders, "Content-Type": "application/json" } },
    );
  } catch (e) {
    console.error("[expire-unaccepted-order] fatal", e);
    return new Response(
      JSON.stringify({ error: e instanceof Error ? e.message : "unknown" }),
      {
        status: 500,
        headers: { ...corsHeaders, "Content-Type": "application/json" },
      },
    );
  }
});
